var e={kind:`array`,render:`cells`,caption:`第一轮 nums = [2,3,5,4,3,1]；第二轮换成完全降序的 [5,4,3,2,1,0]，走 i = −1 的分支`,cells:[`2`,`3`,`5`,`4`,`3`,`1`],frames:[{step:0,note:`第一轮 nums = [2,3,5,4,3,1]。想让这个数变大但尽量少变大，就得在尽量靠右的低位动手，所以从倒数第二格 i = 4 起往左找第一个"能被抬高"的位置。`,marks:{i:4},state:{},band:null,bands:[],aux:{title:`状态板`,rows:[[`当前数组`,`[2,3,5,4,3,1]`,!1],[`分界点 i`,`还在找…`,!1],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`2`,`3`,`5`,`4`,`3`,`1`],rows:[],out:null},{step:0,note:`nums[4] = 3 ≥ 右邻 1，这里还在往下走，抬不高 —— i 继续左移。`,marks:{i:4},state:{4:`bad`},band:{from:5,to:5},bands:[],aux:{title:`状态板`,rows:[[`当前数组`,`[2,3,5,4,3,1]`,!1],[`分界点 i`,`还在找…`,!1],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`2`,`3`,`5`,`4`,`3`,`1`],rows:[],out:null},{step:0,note:`nums[3] = 4 ≥ 右邻 3，这里还在往下走，抬不高 —— i 继续左移。`,marks:{i:3},state:{3:`bad`},band:{from:4,to:5},bands:[],aux:{title:`状态板`,rows:[[`当前数组`,`[2,3,5,4,3,1]`,!1],[`分界点 i`,`还在找…`,!1],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`2`,`3`,`5`,`4`,`3`,`1`],rows:[],out:null},{step:0,note:`nums[2] = 5 ≥ 右邻 4，这里还在往下走，抬不高 —— i 继续左移。`,marks:{i:2},state:{2:`bad`},band:{from:3,to:5},bands:[],aux:{title:`状态板`,rows:[[`当前数组`,`[2,3,5,4,3,1]`,!1],[`分界点 i`,`还在找…`,!1],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`2`,`3`,`5`,`4`,`3`,`1`],rows:[],out:null},{step:0,note:`nums[1] = 3 < 右邻 5，第一次出现上升 —— i = 1 就是分界点。它右边那段 [5,4,3,1] 是降序，自己已经排到最大，动它没用，只能抬高 nums[1]。`,marks:{i:1},state:{1:`hit`},band:{from:2,to:5},bands:[],aux:{title:`状态板`,rows:[[`当前数组`,`[2,3,5,4,3,1]`,!1],[`分界点 i`,`1（值 3）`,!0],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`2`,`3`,`5`,`4`,`3`,`1`],rows:[],out:null},{step:2,note:`nums[5] = 1 ≤ 3，换过来只会让数变小 —— j 左移。`,marks:{i:1,j:5},state:{1:`hit`,5:`bad`},band:{from:2,to:5},bands:[],aux:{title:`状态板`,rows:[[`当前数组`,`[2,3,5,4,3,1]`,!1],[`分界点 i`,`1（值 3）`,!0],[`交换点 j`,`5（值 1）`,!0]],empty:`—`},over:null,cells:[`2`,`3`,`5`,`4`,`3`,`1`],rows:[],out:null},{step:2,note:`nums[4] = 3 和 nums[1] 一样大，换了等于没换，数一点没变大 —— 这就是循环条件写 <= 而不是 < 的原因，j 继续左移。`,marks:{i:1,j:4},state:{1:`hit`,4:`bad`},band:{from:2,to:5},bands:[],aux:{title:`状态板`,rows:[[`当前数组`,`[2,3,5,4,3,1]`,!1],[`分界点 i`,`1（值 3）`,!0],[`交换点 j`,`4（值 3）`,!0]],empty:`—`},over:null,cells:[`2`,`3`,`5`,`4`,`3`,`1`],rows:[],out:null},{step:2,note:`nums[3] = 4 > 3。右段是降序的，从右往左碰到的第一个更大的数，就是"刚好比 3 大"的那个 —— 换它，高位只抬高一丁点。`,marks:{i:1,j:3},state:{1:`hit`,3:`active`},band:{from:2,to:5},bands:[],aux:{title:`状态板`,rows:[[`当前数组`,`[2,3,5,4,3,1]`,!1],[`分界点 i`,`1（值 3）`,!0],[`交换点 j`,`3（值 4）`,!0]],empty:`—`},over:null,cells:[`2`,`3`,`5`,`4`,`3`,`1`],rows:[],out:null},{step:2,note:`交换 nums[1] 和 nums[3]：3 ↔ 4，数组变成 [2,4,5,3,3,1]。整体已经比原来大了，但右段还是乱的（仍是降序），还不是"下一个"。`,marks:{i:1,j:3},state:{1:`hit`,3:`done`},band:{from:2,to:5},bands:[],aux:{title:`状态板`,rows:[[`当前数组`,`[2,4,5,3,3,1]`,!1],[`分界点 i`,`1（值 4）`,!0],[`交换点 j`,`3（值 3）`,!0]],empty:`—`},over:null,cells:[`2`,`4`,`5`,`3`,`3`,`1`],rows:[],out:null},{step:3,note:`要翻的是 nums[2:] = [5,3,3,1]，注意不含分界点自己。这一段现在是降序（这几个数字的最大形态），翻成升序才是最小形态，整体才刚好只大一点点。`,marks:{i:1},state:{2:`active`,3:`active`,4:`active`,5:`active`},band:{from:2,to:5},bands:[],aux:{title:`状态板`,rows:[[`当前数组`,`[2,4,5,3,3,1]`,!1],[`分界点 i`,`1（值 4）`,!0],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`2`,`4`,`5`,`3`,`3`,`1`],rows:[],out:null},{step:3,note:`整段一次性翻转，[5,3,3,1] 变成 [1,3,3,5]（参考解就一句 nums[i+1:] = reversed(nums[i+1:])，没有逐个交换的循环）。结果 [2,4,1,3,3,5]。`,marks:{i:1},state:{2:`done`,3:`done`,4:`done`,5:`done`},band:{from:2,to:5},bands:[],aux:{title:`状态板`,rows:[[`第 1 轮`,`[2,3,5,4,3,1] → [2,4,1,3,3,5]`,!1],[`当前数组`,`[2,4,1,3,3,5]`,!1],[`分界点 i`,`1（值 4）`,!0],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`2`,`4`,`1`,`3`,`3`,`5`],rows:[],out:`第 1 轮：[2,3,5,4,3,1] → [2,4,1,3,3,5]`},{step:0,note:`第二轮换成 [5,4,3,2,1,0]，看看完全降序时会怎样。照样从 i = 4 起往左找分界点。`,marks:{i:4},state:{},band:null,bands:[],aux:{title:`状态板`,rows:[[`第 1 轮`,`[2,3,5,4,3,1] → [2,4,1,3,3,5]`,!1],[`当前数组`,`[5,4,3,2,1,0]`,!1],[`分界点 i`,`还在找…`,!1],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`5`,`4`,`3`,`2`,`1`,`0`],rows:[],out:null},{step:0,note:`nums[4] = 1 ≥ 右邻 0，这里还在往下走，抬不高 —— i 继续左移。`,marks:{i:4},state:{4:`bad`},band:{from:5,to:5},bands:[],aux:{title:`状态板`,rows:[[`第 1 轮`,`[2,3,5,4,3,1] → [2,4,1,3,3,5]`,!1],[`当前数组`,`[5,4,3,2,1,0]`,!1],[`分界点 i`,`还在找…`,!1],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`5`,`4`,`3`,`2`,`1`,`0`],rows:[],out:null},{step:0,note:`nums[3] = 2 ≥ 右邻 1，这里还在往下走，抬不高 —— i 继续左移。`,marks:{i:3},state:{3:`bad`},band:{from:4,to:5},bands:[],aux:{title:`状态板`,rows:[[`第 1 轮`,`[2,3,5,4,3,1] → [2,4,1,3,3,5]`,!1],[`当前数组`,`[5,4,3,2,1,0]`,!1],[`分界点 i`,`还在找…`,!1],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`5`,`4`,`3`,`2`,`1`,`0`],rows:[],out:null},{step:0,note:`nums[2] = 3 ≥ 右邻 2，这里还在往下走，抬不高 —— i 继续左移。`,marks:{i:2},state:{2:`bad`},band:{from:3,to:5},bands:[],aux:{title:`状态板`,rows:[[`第 1 轮`,`[2,3,5,4,3,1] → [2,4,1,3,3,5]`,!1],[`当前数组`,`[5,4,3,2,1,0]`,!1],[`分界点 i`,`还在找…`,!1],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`5`,`4`,`3`,`2`,`1`,`0`],rows:[],out:null},{step:0,note:`nums[1] = 4 ≥ 右邻 3，这里还在往下走，抬不高 —— i 继续左移。`,marks:{i:1},state:{1:`bad`},band:{from:2,to:5},bands:[],aux:{title:`状态板`,rows:[[`第 1 轮`,`[2,3,5,4,3,1] → [2,4,1,3,3,5]`,!1],[`当前数组`,`[5,4,3,2,1,0]`,!1],[`分界点 i`,`还在找…`,!1],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`5`,`4`,`3`,`2`,`1`,`0`],rows:[],out:null},{step:0,note:`nums[0] = 5 ≥ 右邻 4，这里还在往下走，抬不高 —— i 继续左移。`,marks:{i:0},state:{0:`bad`},band:{from:1,to:5},bands:[],aux:{title:`状态板`,rows:[[`第 1 轮`,`[2,3,5,4,3,1] → [2,4,1,3,3,5]`,!1],[`当前数组`,`[5,4,3,2,1,0]`,!1],[`分界点 i`,`还在找…`,!1],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`5`,`4`,`3`,`2`,`1`,`0`],rows:[],out:null},{step:1,note:`i 一路减到 −1，走出了左边界（下标 −1 在数组外，画不出来），说明整个数组从头降到尾 —— 它已经是最大排列，没有更大的了。按题意要回到最小排列，不用交换，直接翻转。`,marks:{},state:{0:`dim`,1:`dim`,2:`dim`,3:`dim`,4:`dim`,5:`dim`},band:{from:0,to:5},bands:[],aux:{title:`状态板`,rows:[[`第 1 轮`,`[2,3,5,4,3,1] → [2,4,1,3,3,5]`,!1],[`当前数组`,`[5,4,3,2,1,0]`,!1],[`分界点 i`,`−1：不存在，整段降序`,!1],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`5`,`4`,`3`,`2`,`1`,`0`],rows:[],out:null},{step:3,note:`要翻的是 nums[0:]，也就是整个数组 [5,4,3,2,1,0]：它是降序（最大形态），翻成升序就是最小形态。i = −1 这个分支不用特判，nums[i+1:] 天然就是整段。`,marks:{},state:{0:`active`,1:`active`,2:`active`,3:`active`,4:`active`,5:`active`},band:{from:0,to:5},bands:[],aux:{title:`状态板`,rows:[[`第 1 轮`,`[2,3,5,4,3,1] → [2,4,1,3,3,5]`,!1],[`当前数组`,`[5,4,3,2,1,0]`,!1],[`分界点 i`,`−1：不存在，整段降序`,!1],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`5`,`4`,`3`,`2`,`1`,`0`],rows:[],out:null},{step:3,note:`整段一次性翻转，[5,4,3,2,1,0] 变成 [0,1,2,3,4,5]（参考解就一句 nums[i+1:] = reversed(nums[i+1:])，没有逐个交换的循环）。结果 [0,1,2,3,4,5]。`,marks:{},state:{0:`done`,1:`done`,2:`done`,3:`done`,4:`done`,5:`done`},band:{from:0,to:5},bands:[],aux:{title:`状态板`,rows:[[`第 1 轮`,`[2,3,5,4,3,1] → [2,4,1,3,3,5]`,!1],[`第 2 轮`,`[5,4,3,2,1,0] → [0,1,2,3,4,5]`,!1],[`当前数组`,`[0,1,2,3,4,5]`,!1],[`分界点 i`,`−1：不存在，整段降序`,!1],[`交换点 j`,`—`,!1]],empty:`—`},over:null,cells:[`0`,`1`,`2`,`3`,`4`,`5`],rows:[],out:`第 2 轮：[5,4,3,2,1,0] → [0,1,2,3,4,5]`}]};export{e as default};